-- P03 Patch 03: request transaction context and project_workflows RLS.
-- REVIEW REQUIRED. Generated by the source patch; NOT applied automatically.
-- Backend request flow: BEGIN -> set_config(local) -> SQL/Drizzle -> COMMIT/ROLLBACK.

BEGIN;

-- Transaction-local GUC values clear themselves at transaction end.
-- This repairs the historical reset_config() call, which is not a PostgreSQL function.
CREATE OR REPLACE FUNCTION public.clear_rls_context()
RETURNS void
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $function$
BEGIN
  PERFORM set_config('app.current_user_id', '', true);
  PERFORM set_config('app.current_role', '', true);
  PERFORM set_config('app.current_project_id', '', true);
END;
$function$;

-- The backend now sets identity and role directly from a verified JWT plus the
-- mapped public.users row. Do not expose legacy arbitrary-user context helpers.
REVOKE ALL ON FUNCTION public.clear_rls_context() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.clear_rls_context() FROM app_runtime;

-- project_workflows was not covered by the earlier RLS migrations.
-- Restrict reads/inserts to active project members or an Admin principal.
ALTER TABLE public.project_workflows ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS pke_project_workflows_member_select ON public.project_workflows;
CREATE POLICY pke_project_workflows_member_select
ON public.project_workflows
FOR SELECT
USING (
  COALESCE(current_setting('app.current_role', true), '') = 'admin'
  OR EXISTS (
    SELECT 1
    FROM public.project_members pm
    WHERE pm.project_id = project_workflows.project_id
      AND pm.user_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid
      AND pm.is_active = true
  )
);

DROP POLICY IF EXISTS pke_project_workflows_member_insert ON public.project_workflows;
CREATE POLICY pke_project_workflows_member_insert
ON public.project_workflows
FOR INSERT
WITH CHECK (
  COALESCE(current_setting('app.current_role', true), '') = 'admin'
  OR EXISTS (
    SELECT 1
    FROM public.project_members pm
    WHERE pm.project_id = project_workflows.project_id
      AND pm.user_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid
      AND pm.is_active = true
  )
);

COMMIT;
